// Wide, swept blade trails with a bright leading edge.
if(hero.attack<.43){const p=project(hero.x,hero.z,.95),t=clamp((hero.attack-.05)/.32,0,1),ang=Math.atan2(hero.fz,hero.fx),a=ang-1.45+t*2.8;ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale,scale*.62);for(let j=0;j<7;j++){ctx.beginPath();ctx.arc(0,0,2.1+j*.09,a-.7,a);ctx.strokeStyle=j<4?'#cce9dd':'#fff1bf';ctx.globalAlpha=(1-t)*(.12+j*.055);ctx.lineWidth=.12;ctx.stroke()}ctx.globalAlpha=1;ctx.restore();}
for(const e of enemies){if(e.hp<=0||e.phase!=='windup')continue;const p=project(e.x,e.z),progress=1-e.timer/1.05;ctx.save();ctx.translate(p.x,p.y);ctx.scale(scale,scale*.62);ellipse(ctx,0,0,2.2,2.2,'#d3734920');ctx.beginPath();ctx.arc(0,0,2.2,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);ctx.strokeStyle='#f6aa71';ctx.lineWidth=.05;ctx.stroke();ctx.restore();}
